}
.instruction svg{flex:none;margin-top:2px;color:var(--brand)}
.pane{display:none;flex:1}
.pane.is-active{display:block;animation:paneIn .28s ease both}
@keyframes paneIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
.cards{
  display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;
}
.card{
  background:var(--surface-2);
