  will-change:transform;
  outline:none;
}
.disc-item:hover{border-color:#c7c3bb;box-shadow:0 5px 14px -12px rgba(40,37,70,.6)}
.disc-item:focus-visible{border-color:var(--brand);box-shadow:0 0 0 3px rgba(92,89,207,.18)}
.disc-item .word{
  flex:1;min-width:0;font-size:13.5px;line-height:1.3;font-weight:550;
