.result-note{color:var(--ink-soft);font-size:13.5px;margin:0 0 26px;max-width:52ch}
.result-actions{display:flex;flex-wrap:wrap;gap:10px}
.scales{
  background:var(--surface);border:1px solid var(--line);border-radius:28px;
  padding:clamp(22px,3.2vw,38px);box-shadow:var(--shadow);
