}
.scales h2{margin:0;font-size:14px;letter-spacing:.02em;text-transform:uppercase;color:var(--ink-faint)}
.scale{display:grid;grid-template-columns:30px minmax(0,1fr) 44px;gap:12px;align-items:center}
.scale-key{
  width:30px;height:30px;border-radius:9px;display:grid;place-items:center;
  font-size:13px;font-weight:800;color:#fff;background:var(--key,var(--brand));
}
.scale-body{min-width:0}
.scale-name{display:flex;justify-content:space-between;gap:8px;font-size:12.5px;color:var(--ink-soft);margin-bottom:6px}
.scale-track{
  position:relative;height:10px;border-radius:999px;background:#eeebe4;overflow:hidden;
}
.scale-track:before{
  content:"";position:absolute;left:50%;top:0;bottom:0;width:1px;background:#c9c4b9;z-index:2;
}
.scale-fill{
  position:absolute;top:0;bottom:0;border-radius:999px;background:var(--key,var(--brand));
  opacity:.92;
}
.scale-value{
  text-align:right;font-size:15px;font-weight:700;font-variant-numeric:tabular-nums;color:var(--ink);
}
.scales-note{margin:2px 0 0;font-size:12px;color:var(--ink-faint);line-height:1.45}
.scales-legend{display:flex;gap:14px;flex-wrap:wrap;font-size:11.5px;color:var(--ink-faint)}
.scales-legend span{display:inline-flex;align-items:center;gap:6px}
.scales-legend i{width:7px;height:7px;border-radius:50%;background:var(--key)}
